import 'package:cloud_firestore/cloud_firestore.dart';
import '../business/business_repository.dart';
import '../../core/models/business.dart';
import '../goals/goal_repository.dart';
class AurenCampaignPlan{final String businessId,businessName,objective,audience,channel;final List<String> contentIdeas,steps,metrics;final DateTime generatedAt;const AurenCampaignPlan({required this.businessId,required this.businessName,required this.objective,required this.audience,required this.channel,required this.contentIdeas,required this.steps,required this.metrics,required this.generatedAt});Map<String,dynamic> toMap()=>{'businessId':businessId,'businessName':businessName,'objective':objective,'audience':audience,'channel':channel,'contentIdeas':contentIdeas,'steps':steps,'metrics':metrics,'generatedAt':Timestamp.fromDate(generatedAt.toUtc())};}
class CampaignAiService{final FirebaseFirestore _db;final BusinessRepository _businesses;final GoalRepository _goals;CampaignAiService({FirebaseFirestore? firestore,BusinessRepository? businesses,GoalRepository? goals}):_db=firestore??FirebaseFirestore.instance,_businesses=businesses??BusinessRepository(),_goals=goals??GoalRepository();Future<AurenCampaignPlan> build(String uid,{String? businessId,String objective='زيادة الوصول والعملاء',String audience='عملاء محتملون',String channel='Pulse'})async{final businesses=await _businesses.watchPublic().first;final owned=businesses.where((b)=>b.ownerId==uid).toList();AurenBusiness? b;for(final x in owned){if(x.id==businessId){b=x;break;}}b??=(owned.isEmpty?null:owned.first);final goals=await _goals.watch(uid).first;final active=goals.where((g)=>g.status=='active').toList();final goal=active.isEmpty?'':active.first.title;final name=b?.name??'نشاطي التجاري';final obj=goal.isEmpty?objective:'دعم الهدف: '+goal;final category=b?.category??'عام';final ideas=['منشور تعريفي يوضح قيمة '+name,'محتوى قصير يشرح فائدة المنتج أو الخدمة في '+category,'قصة نجاح أو تجربة عميل','دعوة واضحة للتواصل أو طلب عرض'];final steps=['حدد عرضًا واحدًا ورسالة أساسية','أنشئ 3 قطع محتوى بصيغ مختلفة','انشر واختبر توقيتين أو صياغتين','سجّل الاستجابة وكرر ما يحقق تفاعلًا أفضل'];final metrics=['الوصول والمشاهدات','نسبة التفاعل','المحادثات أو الاستفسارات','طلبات الشراء أو الخدمة','التحويل من فرصة إلى عميل'];final plan=AurenCampaignPlan(businessId:b?.id??'',businessName:name,objective:obj,audience:audience,channel:channel,contentIdeas:ideas,steps:steps,metrics:metrics,generatedAt:DateTime.now());await _db.collection('users').doc(uid).collection('campaign_ai_plans').doc('current').set(plan.toMap());return plan;}}